#' Bacon, Pre-trend and HonestDiD
#'
#' Diagnostics for staggered-adoption designs: Goodman-Bacon decomposition, 
#' TWFE weights, joint pre-trend tests and HonestDiD sensitivity analysis.
#'
#' @examples
#' \donttest{
#' # d is a data frame with one row per unit and period
#' didiag(data = d, dep = 'y', id = 'id', time = 'year', treat = 'D')
#'}
#' @param data .
#' @param dep a string naming the outcome variable in \code{data}
#' @param id a string naming the unit identifier variable in \code{data}
#' @param time a string naming the period variable in \code{data}; values must
#'   be integers (a year or a period number)
#' @param treat a string naming the treatment variable in \code{data}: a 0/1
#'   indicator that never turns off, or the first treated period (see
#'   \code{treatType})
#' @param treatType \code{'indicator'} (default) if \code{treat} is a 0/1
#'   treatment indicator, or \code{'cohort'} if it holds the first treated
#'   period (0 or missing = never treated)
#' @param bacon \code{TRUE} (default) or \code{FALSE}, Goodman-Bacon
#'   decomposition of the static TWFE estimate (balanced panels)
#' @param weights \code{TRUE} (default) or \code{FALSE}, weights that the
#'   static TWFE estimate puts on treated observations
#' @param pretest \code{TRUE} (default) or \code{FALSE}, joint Wald tests that
#'   the pre-treatment effects are zero
#' @param honest \code{TRUE} or \code{FALSE} (default), HonestDiD sensitivity
#'   analysis with relative-magnitude restrictions (slow)
#' @param honestBase \code{'cs'} (default) or \code{'sa'}, the event study the
#'   sensitivity analysis is based on
#' @param honestTarget \code{'first'} (default, first post-treatment period)
#'   or \code{'average'} (average of the post-treatment periods)
#' @param honestMbar the largest relative magnitude Mbar of the grid (default
#'   2)
#' @param ptpower \code{TRUE} or \code{FALSE} (default), compute the power of
#'   the conventional pre-trend test against a hypothesized linear violation of
#'   parallel trends
#' @param ptBase \code{'sa'} (default) or \code{'cs'}, the event study the
#'   pre-trend power is computed for
#' @param ptSlope the slope per event period of the linear violation of
#'   parallel trends to detect; 0 (default) reports only the slopes that the
#'   test detects with 50 and 80 percent power
#' @param csControl \code{'nevertreated'} (default) or \code{'notyettreated'},
#'   the control group used by Callaway and Sant'Anna
#' @param minE the most negative event time shown (default -4)
#' @param maxE the largest event time shown (default 4)
#' @param ciLevel the confidence level in percent (default 95)
#' @param plotPalette \code{'color'} (default, colour-blind safe) or
#'   \code{'gray'} (shades, shapes and line types for printing)
#' @param showHelp \code{TRUE} or \code{FALSE} (default), show notes on what
#'   the method does and how to read the results
#' @param showGuide \code{TRUE} or \code{FALSE} (default), show a guide to the
#'   variables and the data format
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bacon} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$baconPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pretest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$honest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$honestPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ptTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ptPost} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ptPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$bacon$asDF}
#'
#' \code{as.data.frame(results$bacon)}
#'
#' @export
didiag <- function(
    data,
    dep,
    id,
    time,
    treat,
    treatType = "indicator",
    bacon = TRUE,
    weights = TRUE,
    pretest = TRUE,
    honest = FALSE,
    honestBase = "cs",
    honestTarget = "first",
    honestMbar = 2,
    ptpower = FALSE,
    ptBase = "sa",
    ptSlope = 0,
    csControl = "nevertreated",
    minE = -4,
    maxE = 4,
    ciLevel = 95,
    plotPalette = "color",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("didiag requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(treat), treat, NULL))


    options <- didiagOptions$new(
        dep = dep,
        id = id,
        time = time,
        treat = treat,
        treatType = treatType,
        bacon = bacon,
        weights = weights,
        pretest = pretest,
        honest = honest,
        honestBase = honestBase,
        honestTarget = honestTarget,
        honestMbar = honestMbar,
        ptpower = ptpower,
        ptBase = ptBase,
        ptSlope = ptSlope,
        csControl = csControl,
        minE = minE,
        maxE = maxE,
        ciLevel = ciLevel,
        plotPalette = plotPalette,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- didiagClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

